# Own-wording magic items of Griffon's Saddlebag, Book 1 (2024), chunk C: Mantle of the Pack Lord to Shaedenstaff. Row shape as tghp_item.py.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Mantle of the Pack Lord", "Wondrous Item", "Rare", 0, "A pelt cloak that breaks up pack tactics. Enemies do not gain Advantage on attack rolls against you just because an ally of theirs is within 5 ft of you, such as from Pack Tactics.")

add("Mask of Dendallen", "Wondrous Item", "Very Rare", 1, "A skull mask with 5 charges that returns all of them at dusk. Spend 1 charge to cast Bestow Curse, Fear, Speak with Dead or Tongues (save DC 16). You have Advantage on Constitution saves to keep Concentration on those spells and you understand any writing you see.\n**Curse.** On first wearing, make a DC 16 Intelligence save. On a pass you can pull it off at once. On a fail you take 5d10 Psychic damage, cannot remove it without Remove Curse or similar magic, lose smell and taste (you auto-fail Perception checks that need them), and take 1d10 Psychic damage whenever you roll a 1 on a D20 Test. After removal, your face needs 1d4 days to heal and your voice changes.", ch=[5, "all", "dusk"])
SP["Mask of Dendallen"] = {"sp": [["Bestow Curse", 1], ["Fear", 1], ["Speak with Dead", 1], ["Tongues", 1]], "dc": 16}

add("Mask of the Pact Bearer", "Wondrous Item", "Uncommon", 1, "The mask takes the face of your patron when you attune. Once per dawn you can cast one spell from your level 3 Warlock subclass spell table without a slot. Its level cannot exceed your Warlock slot level, and it is cast at its lowest level.", by="Warlock", ch=[1, "1", "dawn"])

add("Master Machinist's Marvelous Mallet", "Weapon", "Rare", 1, "A mirror-polished silver Light Hammer with +1 to attack and damage rolls. It has 7 charges and regains 1d6 + 1 at dawn. Spend 1 charge to cast Mending from it, affecting an area up to 5 ft on a side. Or spend 3 charges as a Bonus Action and touch armor to give its wearer +1 AC for 1 minute (one such effect per creature).", fx={"atk": 1, "dmg": 1}, base=["Light Hammer"], ch=[7, "1d6+1", "dawn"])
SP["Master Machinist's Marvelous Mallet"] = {"sp": [["Mending", 1]]}

add("Mastery Gem", "Wondrous Item", "Legendary", 0, "A red gem, immune to all damage, that overrides an attunement requirement you fail. Hold it to an item (not Legendary or an Artifact) and you can attune anyway. The gem fuses to the item, and ending attunement frees you even from a curse. When it detaches it strips the item's magic, leaving it mundane.")

add("Merry Berry", "Wondrous Item", "Common", 0, "A sweet fruit that tastes like shortbread when raw. When cooked properly, the eater has Advantage on Intelligence and Wisdom checks that rely on smell or taste, and on checks with Cook's Utensils, for 24 hours. Overcooking removes the benefit.")

add("Mirrorlight Edge", "Weapon", "Rare", 1, "A crystal Scimitar. As a Magic action, command it to make up to 2 ghostly projections that last until you dismiss them. When you miss while it has a projection, dismiss one to reroll the d20. When you hit, you deal an extra 1d4 Slashing per projection. It sheds Dim Light in 10 ft with one projection and 20 ft with two.", base=["Scimitar"], xd=["Per projection: +1d4 Slashing"])

add("Mirrorlight Piercer", "Weapon", "Very Rare", 1, "A crystal Spear with +2 to attack and damage rolls and the Light property. With a free hand, use a Magic action and a command word to make a ghostly copy in that hand, and make one attack with either. A thrown copy vanishes and then reforms. The copy lasts 1 minute or until you dismiss it as a Bonus Action. The Spear sheds Bright Light in 10 ft and Dim Light for 10 ft more while a copy exists.", fx={"atk": 2, "dmg": 2}, base=["Spear"])

add("Mockingblade", "Weapon", "Uncommon", 1, "A Shortsword you are proficient with while attuned. It has 6 charges and regains 1d4 + 2 at dawn. When you hit on your turn, spend a Bonus Action and 1 charge to cast Vicious Mockery on the target with your spell save DC. If the target rolls a 20 on the save, the hilt screams at you and the next attack against you has Advantage until your next turn, and the sword cannot cast it again for 1d4 days.", by="Bard", base=["Shortsword"], ch=[6, "1d4+2", "dawn"])
SP["Mockingblade"] = {"sp": [["Vicious Mockery", 1]]}

add("Monocle of Clarity", "Wondrous Item", "Rare", 0, "A lens with three filters and 4 charges, regaining 1d3 + 1 at dawn. As a Magic action, spend 1 charge to activate one filter for up to 1 hour. Comprehend Languages lets you understand any writing you see, Darkvision gives 60 ft, and See Invisibility reveals Invisible creatures and objects.", ch=[4, "1d3+1", "dawn"])

add("Monsterbane Lasher", "Weapon", "Very Rare", 0, "A mithral Whip with +1 to attack and damage rolls and an extra 1d4 Slashing on a hit. Its seven runes match Acid, Cold, Fire, Lightning, Poison, Radiant and Thunder. On a melee hit, channel one or more runes to add 2d4 of each chosen type. A rune you channel cannot be used again until dawn.", fx={"atk": 1, "dmg": 1}, base=["Whip"], xd=["Always: +1d4 Slashing", "Per rune: +2d4 of its type"])

add("Necrolace", "Wondrous Item", "Rare", 1, "A necklace that holds up to 3 charges and starts with 1d3. It gains 1 charge when you reduce a Small or larger enemy to 0 HP. As a Bonus Action, spend charges to take 1d8 Necrotic damage each (ignores Resistance and Immunity), and a creature you see within 30 ft regains twice that in HP. If this drops you to 0 HP you are Unconscious but Stable, and the target regains twice your remaining HP instead.", by="Spellcaster", ch=[3, "0", "never", "Starts with 1d3. Gains 1 per kill"])

add("Nightstalker's Kanabo", "Weapon", "Very Rare", 1, "A studded Greatclub with +1 to attack and damage rolls and the Heavy property. It deals an extra 2d8 Psychic damage to an Unconscious target. On a natural 20, the target makes a DC 16 Constitution save or is Unconscious until the end of your next turn (damage or a shake ends it, and creatures that do not sleep or are immune to Exhaustion pass). It has 3 charges, regaining 1d3 at dusk. Spend 1 charge as a Bonus Action to cast Invisibility (self only) or Sleep.", fx={"atk": 1, "dmg": 1}, base=["Greatclub"], ch=[3, "1d3", "dusk"], xd=["Unconscious target: +2d8 Psychic"])
SP["Nightstalker's Kanabo"] = {"sp": [["Invisibility", 1], ["Sleep", 1]]}

add("Null Chalk", "Wondrous Item", "Very Rare", 0, "A pouch with 1d4 + 1 chalk sticks. As a Magic action, a stick draws a continuous line up to 50 ft long and 1 ft thick that lasts 8 hours, and the stick crumbles. Magic cannot cross it, creatures behind it have Cover against magic from the far side, and magic items crossing it turn mundane for 1 round. The first Celestial, Elemental, Fey, Fiend or Undead to cross on a turn makes a DC 16 Charisma save. On a fail it takes 2d8 Force damage, is pushed back up to 10 ft and has Speed 0 until its next turn. On a pass it takes half damage and crosses. Dispel Magic treats the line as a level 6 spell.")

add("Omenbringer's Mantle", "Wondrous Item", "Very Rare", 1, "A raven-feathered mantle. You have Resistance to Necrotic damage and fall at 60 ft per round without taking fall damage. You can cast Find Familiar from it as a Magic action, and the familiar is a Raven. If it drops to 0 HP, it cannot be summoned again until dusk.", fx={"res": ["Necrotic"]})
SP["Omenbringer's Mantle"] = {"sp": [["Find Familiar", 0]]}

add("Orator's Quill", "Wondrous Item", "Common", 0, "A red quill that writes what you say. Use a Bonus Action and a command word to activate it, then it floats and writes your words on a still surface, starting a new line at the edge. You must be within 15 ft and it cannot hear you behind Cover. It stops on the command word again or after 1 minute of silence.")

add("Otyugh Cloak", "Wondrous Item", "Uncommon", 1, "An otyugh pelt with a 3 ft eye tendril on the hood. As a Magic action you can send a simple message or image telepathically to a creature you see within 60 ft that understands a language, with no reply possible. The tendril can do simple tasks within 5 ft (no attacks, no magic items, 10 lb limit). As a Bonus Action with eyes closed, you see through it and gain Darkvision 60 ft.")

add("Ouroboros Rapier", "Weapon", "Very Rare", 1, "A Rapier with +1 to attack and damage rolls. Each 8 on a damage die adds 1d8 Poison damage. On a natural 20 against a creature, it makes a DC 15 Constitution save. On a fail it takes 3d6 Poison damage and is Poisoned for 1 minute. On a pass it takes half damage only.", fx={"atk": 1, "dmg": 1}, base=["Rapier"], xd=["Natural 20: DC 15 Con, 3d6 Poison and Poisoned"])

add("Overshield", "Armor", "Uncommon", 1, "A large Shield that gives +1 AC on top of its normal bonus. The bonus is +2 while you have any Temporary HP, and the Shield glows blue. As a Magic action, gain 1d6 + 8 Temporary HP. Once used, it works again at the next dawn.", fx={"ac": 1}, base=["Shield"], ch=[1, "1", "dawn"])

add("Pack of LeviBubble Sugarbombs", "Wondrous Item", "Uncommon", 0, "A pack of five gum pieces. Chew one for 1 minute, then as a Magic action blow a bubble 1 ft wide to gain the effect of Levitate (no Concentration) for up to 10 minutes. It ends early if you pop the bubble or it takes damage. You can instead stick the bubble to another creature or loose object within 5 ft. An unwilling target can avoid it with a DC 13 Dexterity save. The gum is mundane afterward.")

add("Pair of Tiny Violin Rings", "Ring", "Common", 0, "A pair of golden rings that play a sad tune when rubbed together. A creature that knows Vicious Mockery can use them as the Somatic component of that cantrip instead of the Verbal one.")

add("Pearl of Wisdom Quiver", "Wondrous Item", "Rare", 1, "A quiver made from a giant oyster shell. Arrows drawn from it are magical, ignore the penalties of underwater ranged combat, and turn mundane once they hit or someone else holds them. Use a command word to make a magical pearl. A creature holding it can take Advantage on one Wisdom check or save, which turns the pearl to dust. An unused pearl fades after 24 hours. Works once per dawn.", ch=[1, "1", "dawn"])

add("Pendant of the Tempered Fury", "Wondrous Item", "Very Rare", 1, "A silvered pendant holding a flaming fist. If you wear no armor and carry no Shield, you reduce Bludgeoning, Piercing and Slashing damage you take by 3. It has 3 charges and regains 1d3 at dawn. As a Bonus Action, spend 1 charge to wreathe your hands in flame for 1 minute, shedding Bright Light in 10 ft and Dim Light for 10 ft more. Your Unarmed Strike can then deal Fire damage and adds 1d4 Fire on a hit. The flames never harm you.", ch=[3, "1d3", "dawn"], xd=["Flaming hands: Unarmed Strike +1d4 Fire"])

add("Pendant of Thieves' Sight", "Wondrous Item", "Uncommon", 0, "You know Thieves' Cant while wearing it. You also gain a +5 bonus to Intelligence checks to understand a written or spoken cipher.")

add("Peppermince Sugarbomb", "Wondrous Item", "Uncommon", 0, "A mint candy that dissolves over 1 hour. As a Bonus Action, crunch it to take 1d6 Piercing damage. For 1 minute, your weapon and Unarmed Strike hits that deal Piercing or Slashing damage deal 2 extra damage. **Upset Stomach.** Only one sugarbomb of this kind works at a time. Eating another while one is active replaces it and forces a DC 13 Constitution save or you are Poisoned for 1 minute.")

add("Periapt of Reflection", "Wondrous Item", "Rare", 1, "A mirror-bright charm. When you fail an Intelligence, Wisdom or Charisma save, take a Reaction to reroll it and keep the new result.\n**Curse.** Rolling a 1 on such a reroll curses you until Remove Curse or similar magic, even if you take the periapt off. While cursed, the periapt dulls to gray, your reflection within 10 ft looks horrifying, and you take 1d8 Psychic damage whenever you fail an Intelligence, Wisdom or Charisma save.")

add("Permanent Parchment", "Wondrous Item", "Common", 0, "A violet sheet that you lock or unlock with a Bonus Action and the words lock or unlock. While locked, it cannot be torn, burned or soaked, and ink on it cannot be changed without magic, and new ink runs off. While unlocked, it acts as plain paper, and the word clear wipes all ink from it.")

add("Petal Dancer Ward", "Wondrous Item", "Uncommon", 1, "A cape of fragrant petals that drift behind you. A Bonus Action changes their color. You can cast Druidcraft from it, and Beasts and Plant creatures have Disadvantage on Opportunity Attacks against you.")
SP["Petal Dancer Ward"] = {"sp": [["Druidcraft", 0]]}

add("Phase Axe", "Weapon", "Rare", 1, "A near-transparent Battleaxe with +1 to attack and damage rolls and the Thrown property (20/60 ft). The first time on your turn you hit with a ranged attack, another creature within 10 ft of the target makes a DC 15 Dexterity save or takes 1d8 Force damage. If you see the axe within 60 ft, a Bonus Action calls it to your hand, passing through obstacles up to 5 ft thick that are not lead.", fx={"atk": 1, "dmg": 1}, base=["Battleaxe"])

add("Pike of the Forgotten Legion", "Weapon", "Legendary", 1, "A Pike with +2 to attack and damage rolls and 6 charges, regaining 1d4 + 2 at dusk. Spend charges to cast Mirror Image (1), Phantom Steed (1), Speak with Dead (1) or Spirit Guardians (2), save DC 17.\n**Spectral Warrior.** Once per turn on a hit, the target has Disadvantage on attacks against you until your next turn. It has no effect on Undead.\n**Haunting Phalanx.** Magic action, 3 charges: spectral pikemen march in a 25 ft wide, 50 ft long Line. Each creature makes a DC 17 Intelligence save (Undead pass), taking 3d10 Necrotic and 3d10 Psychic and the Spectral Warrior effect on a fail, or half damage on a pass.", fx={"atk": 2, "dmg": 2}, base=["Pike"], ch=[6, "1d4+2", "dusk"])
SP["Pike of the Forgotten Legion"] = {"sp": [["Mirror Image", 1], ["Phantom Steed", 1], ["Speak with Dead", 1], ["Spirit Guardians", 2]], "dc": 17}

add("Plaguebane Mask", "Wondrous Item", "Rare", 0, "A bird-beaked mask that purifies airborne toxins. You have Advantage on saves to avoid or end Poisoned and airborne magical contagions, and Resistance to Poison damage from those effects. It has 3 charges and regains 1d3 at dawn. As a Magic action, spend 1 charge to exhale a 15 ft Cone of pollen. Each creature makes a DC 15 Constitution save, taking 2d8 Poison and having its Speed halved until the end of its next turn on a fail (not if immune to Poisoned), or half damage only on a pass.", ch=[3, "1d3", "dawn"])

add("Planar Rapier", "Weapon", "Very Rare", 1, "A Rapier with +2 to attack and damage rolls and 5 charges, regaining 1d4 + 1 at dawn. When you make a melee attack, spend 1 charge to add 5 ft of reach. Or spend 1 charge after a melee attack on a target within 5 ft to make a second melee attack against a creature 5 ft behind it, which must be within 10 ft of you. Each charge spent adds 2d8 Force damage on a hit.", fx={"atk": 2, "dmg": 2}, base=["Rapier"], ch=[5, "1d4+1", "dawn"], xd=["Per charge: +2d8 Force"])

add("Pomade of Ten Thousand Styles", "Wondrous Item", "Common", 0, "A canister that changes your hair color, style, thickness and length (up to 1 ft longer or shorter) for 1 minute of application per use. It holds 4 uses and regains 1d4 at dawn. The change fades after a Long Rest unless you repeat it for 7 days, which makes it permanent. Cut hair turns to dust after 24 hours.", ch=[4, "1d4", "dawn"])

_PDB = "Drinking it gives you 1 minute to replace one attack of the Attack action with a breath like the Dragonborn Breath Weapon. The damage type is rolled on the Draconic Ancestors table at creation. Uncommon is 2d10 with DC 13, Rare is 3d10 with DC 15, Very Rare is 4d10 with DC 16. A potion crafted from a dragon's stomach and gizzard takes that dragon's type, with rarity set by age: young Uncommon, adult Rare, ancient Very Rare. Crafting needs 2 hours of work per day or you roll 1d20, and on a 1 the materials are ruined."
add("Potion of Dragon's Breath", "Potion", "Unknown", 0, _PDB)
add("Potion of Dragon's Breath (Uncommon)", "Potion", "Uncommon", 0, _PDB)
add("Potion of Dragon's Breath (Rare)", "Potion", "Rare", 0, _PDB)
add("Potion of Dragon's Breath (Very Rare)", "Potion", "Very Rare", 0, _PDB)

add("Potion of Spell Recovery", "Potion", "Rare", 0, "Drinking it restores expended spell slots of your choice, each of level 1 to 5, with a combined level of 1d3 + 3 or less.")

add("Precipit, the Formless", "Staff", "Artifact", 1, "A coral staff from the Plane of Water that works as a Quarterstaff (Topple). Attuned, you breathe underwater, ignore deep-water drawbacks and have Resistance to Cold damage. It has 15 charges and regains 1d8 + 7 at dawn. As a Bonus Action, set it to gas, liquid or solid, or spend 1 charge as a Reaction to change at once.\n**Gas.** Resist Bludgeoning and Piercing, +10 ft Speed, Fly Speed equal to your Speed, move through creatures, and Disadvantage on Opportunity Attacks against you. Spells (DC 18): Cloudkill 5, Fog Cloud 1, Gaseous Form 3, Misty Step 2, Wind Walk 6. Tailwind (2 charges): you and allies within 30 ft Dash as a Bonus Action and avoid Opportunity Attacks until the end of your next turn.\n**Liquid.** Resist Bludgeoning and Slashing, +10 ft Speed, Swim Speed equal to your Speed, walk on liquid, and redirect a melee miss against you. Spells (DC 18): Blur 2, Control Water 4, Create or Destroy Water 1, Mirror Image 2, Water Breathing 3. Tide Turner (3 charges): enemies within 30 ft make a DC 18 Strength save, taking 4d8 Bludgeoning and a 20 ft push or pull on a fail, or half damage on a pass.\n**Solid.** Resist Piercing and Slashing, Speed 5 ft, +3 AC, halved forced movement, and 10 Temporary HP at the start of each turn. Spells (DC 18, +10 to hit): Cone of Cold 5, Ice Storm 4, Ray of Frost 0 (1 at level 5), Wall of Ice 6. Deep Freeze (4 charges): enemies within 30 ft make a DC 18 Constitution save, taking 4d8 Cold and Speed 0 until the end of their next turn on a fail, or half damage and half Speed on a pass.\nIt can only be destroyed by 100 years without water on the Plane of Water.", fx={"res": ["Cold"]}, base=["Quarterstaff"], ch=[15, "1d8+7", "dawn"])
SP["Precipit, the Formless"] = {"sp": [["Cloudkill", 5], ["Fog Cloud", 1], ["Gaseous Form", 3], ["Misty Step", 2], ["Wind Walk", 6], ["Blur", 2], ["Control Water", 4], ["Create or Destroy Water", 1], ["Mirror Image", 2], ["Water Breathing", 3], ["Cone of Cold", 5], ["Ice Storm", 4], ["Ray of Frost", 0], ["Wall of Ice", 6]], "dc": 18}

add("Prismatic Javelin", "Weapon", "Uncommon", 1, "A dark crystal Javelin that returns to your hand after a ranged hit. Once per dawn, throw it at a point within 120 ft as a Magic action to burst into Bright Light in 20 ft and Dim Light for 20 ft more. Each creature of your choice there not behind Cover makes a DC 13 Dexterity save. On a fail it takes 2d10 damage from a beam rolled on 1d6: 1 Red Fire, 2 Orange Acid, 3 Yellow Lightning, 4 Green Poison, 5 Blue Cold, 6 hit by two beams (reroll any 6).", base=["Javelin"], ch=[1, "1", "dawn"])

add("Profane Mask", "Wondrous Item", "Common", 0, "A cloth mask that turns your spoken words into angry insults and swears, which you do not hear. A Study action and a DC 10 Intelligence (Investigation) check shows the words are not yours. Verbal components, command words and actual obscenities are heard normally.")

add("Purging Dagger", "Weapon", "Very Rare", 1, "A holy wood Dagger with +1 to attack and damage rolls and an extra 1d4 Radiant on a hit, rising to 2d4 against Undead. On a natural 20 against an Undead, you can leave it lodged in the target. It then sheds sunlight (Bright 15 ft, Dim 15 ft more) and deals 3d4 Radiant at the start of the target's turns. Pulling it out takes an action and a DC 16 Strength (Athletics) check, and it then returns to the ground at your feet or your free hand.", fx={"atk": 1, "dmg": 1}, base=["Dagger"], xd=["Always: +1d4 Radiant", "Undead: +2d4 Radiant instead"])

add("Purity Spear", "Weapon", "Legendary", 1, "A unicorn-horn Spear with +2 to attack and damage rolls. Attuned, you are immune to Poison damage and Poisoned, and have Advantage on Constitution and Wisdom saves against spells and magical effects. It has 10 charges, regaining 1d6 + 4 at dawn. Spend charges to cast Calm Emotions 2, Detect Evil and Good 1, Dispel Evil and Good 5, Greater Restoration 5, Misty Step 2 or Purify Food and Drink 1 (DC 17). As a Magic action, spend 1 charge to heal a touched creature 2d8 + 2 HP and end Poisoned on it.\n**Charge.** Moving 20 ft straight at a target before a melee hit adds 2d8 Piercing.\n**Curse Breaker.** You cannot be cursed, and existing curses on you are suppressed while attuned.", fx={"atk": 2, "dmg": 2, "imm": ["Poison"], "condImm": ["Poisoned"]}, by="Creature of Good Alignment", base=["Spear"], ch=[10, "1d6+4", "dawn"], xd=["Moved 20 ft straight: +2d8 Piercing"])
SP["Purity Spear"] = {"sp": [["Calm Emotions", 2], ["Detect Evil and Good", 1], ["Dispel Evil and Good", 5], ["Greater Restoration", 5], ["Misty Step", 2], ["Purify Food and Drink", 1]], "dc": 17}

add("Purse Piglet", "Wondrous Item", "Rare", 0, "A ceramic piggy bank that animates once you drop in a coin and cork it, and treats you as its owner. It eats coins (up to 1,000 per hour), tells you its total when shaken, and spits out exact change on request, even converting denominations. It keeps at least 1 Copper Piece unless you remove it. It follows you or a designated ally, vanishes into a pocket dimension if none is within 30 ft, and is summoned or sent away with a Bonus Action and its command phrase.\nIt is a Tiny object with AC 10 and 5 HP, immune to Poison and Psychic, and vulnerable to Bludgeoning. At 0 HP it shatters and returns after 1d4 days. Putting it in a Bag of Holding, Portable Hole or similar space destroys both and opens an Astral Plane gate that pulls in creatures within 10 ft.")

add("Puzzle Ring of Vitality, Life, and Power", "Ring", "Legendary", 1, "A golden ring with a silver puzzle ring of three bands. You can use Lay On Hands on a creature up to 10 ft away. As a Study action, solve one band at a time in order. Band one is DC 5 Intelligence (Investigation) and starts a 30 ft Emanation for 1 minute that restores 2d6 HP to one creature in it at creation and the start of each of your turns. Band two is DC 10 and gives you and allies Resistance to Necrotic, protects HP maximums, and brings an ally at 0 HP to 1 HP at the start of its turn. Band three is DC 15 and gives you and allies Advantage on saves against spells and magical effects, and no damage on a successful half-damage save. The aura ends if you remove the ring or drop to 0 HP, and then the ring waits 1 day per band solved. If you solved all three, roll 1d3, and on a 1 or 2 reduce the wait by that number, on a 3 it is ready at once.", by="Paladin")

add("Quagmire Maul", "Weapon", "Very Rare", 1, "A damp, withered Maul with +2 to attack and damage rolls and 10 charges, regaining 1d6 + 4 at dawn. As a Magic action, spend 1 or more charges and slam it down within 5 ft to turn a 5 ft radius into a swamp of Difficult Terrain for 1 minute, plus 5 ft radius per extra charge. You cross it as normal terrain. If you spend the last charge, roll 1d20, and on a 1 the maul turns to muck and is destroyed.", fx={"atk": 2, "dmg": 2}, base=["Maul"], ch=[10, "1d6+4", "dawn"])

add("Quake Hammer", "Weapon", "Rare", 1, "A Light Hammer with +2 to attack and damage rolls. Once per dawn, as a Magic action, smash it down within 5 ft or throw it at a point within 60 ft to shake a 10 ft radius. Each creature there except you makes a DC 15 Dexterity save, taking 2d6 Bludgeoning and falling Prone on a fail, or half damage only on a pass.", fx={"atk": 2, "dmg": 2}, base=["Light Hammer"], ch=[1, "1", "dawn"])

add("Quickdraw", "Weapon", "Rare", 0, "A concealed Hand Crossbow worn on the wrist or forearm that needs no free hand. You must also wear two rings on adjacent fingers, one with a string and one with a tiny blade. Severing the string fires it. Reloading and resetting takes 1 minute. While loaded, you can attack with it as a Bonus Action, or as a Reaction at the start of your first turn of combat.", base=["Hand Crossbow"])

add("Quicksilver Clay", "Wondrous Item", "Common", 0, "A 1-inch orb of dry, silvery liquid. As a Magic action, shape it into any form no larger than your palm. It stays liquid, reverts at will with no action, and reverts at once if it leaves your hand. Swallowing it is harmless and it passes in 1d4 days.")

add("Radiant Defender", "Weapon", "Rare", 1, "A Maul with a guard shield over the handle and +1 to attack and damage rolls. When you take the Dodge action while wielding it, you gain +2 AC until your next turn. If a creature within 5 ft misses you while you benefit from Dodge, use a Reaction to attack it with the Maul, adding 1d8 Radiant on a hit. Using that Reaction ends the AC bonus until you Dodge again.", fx={"atk": 1, "dmg": 1}, base=["Maul"], xd=["Reaction hit: +1d8 Radiant"])

add("Reap and Sew", "Weapon", "Rare", 1, "A Light Crossbow with +2 to attack and damage rolls that deals Force damage. You can cast Mending from it. Its special needle Bolt returns and reloads itself after each attack, so you ignore Loading. It has 4 charges and regains 1d4 at dawn. When you hit a Large or smaller creature with that Bolt, spend 1 charge to tether it to a point within 5 ft of it. If it moves more than 10 ft away before the end of its next turn, it makes a DC 15 Strength save or has Speed 0 until your next turn. A lost Bolt returns after 24 hours.\n**Curse.** Attuning curses you. Each time you start a Short or Long Rest you make a DC 12 Wisdom save, and on a fail you must sew or knit feverishly for at least 1 hour first.", fx={"atk": 2, "dmg": 2}, base=["Light Crossbow"], ch=[4, "1d4", "dawn"])
SP["Reap and Sew"] = {"sp": [["Mending", 0]]}

add("Red Claw's Regalia", "Wondrous Item", "Legendary", 1, "A dragon scale robe that is warm and comfortable. You tolerate temperatures of 0 degrees F or lower, your Constitution rises by 2 (maximum 22), you have Advantage on Constitution saves and Resistance to Fire damage, and you can walk on molten rock as if solid. Harmless embers and scorch marks trail your steps.", fx={"res": ["Fire"]})

add("Relentless Bulwark", "Armor", "Uncommon", 1, "A sturdy metal Shield with 6 charges, regaining 1d4 + 2 at dawn. Spend 1 charge to cast Shield of Faith from it. If you fail a Constitution save to hold that Concentration, you can spend another charge as a Reaction to pass instead, while holding the Shield.", by="Cleric or Paladin", base=["Shield"], ch=[6, "1d4+2", "dawn"])
SP["Relentless Bulwark"] = {"sp": [["Shield of Faith", 1]]}

add("Retaliating Bloom Shield", "Armor", "Rare", 0, "A steel Shield with a hidden chamber of toxic pollen. While holding it, when a Large or smaller creature you see within 5 ft misses you, use a Reaction to blast it. It makes a DC 15 Constitution save, taking 3d10 Poison and becoming Poisoned for 1 minute on a fail, or half damage on a pass. Works again at the next dusk, or you can reset the plates by hand over 1 minute.", base=["Shield"], ch=[1, "1", "dusk"])

add("Retaliating Shield of Ink", "Armor", "Uncommon", 0, "A Shield that sprays squid ink. When a Large or smaller creature within 5 ft misses you, use a Reaction to spray it. The attacker makes a Dexterity save or is Blinded until the start of its next turn. The DC is 13 with squid ink (20+ gp) or 10 with common ink (10 gp). It holds 3 uses and takes 1 minute to refill. A Study action and DC 12 Intelligence (Investigation) check reveals how it works. Filling it with acid, poison, grog, oil or sand damages it and takes 8 hours to repair.", base=["Shield"], ch=[3, "0", "never", "Refill takes 1 minute"])

add("Ring of Anchoring", "Ring", "Rare", 1, "A lead ring that lets you breathe underwater and cuts any forced movement against you by 10 ft.\n**Curse.** Attuning curses you until Remove Curse or similar magic, or until the ring finger is severed. You cannot remove it, and underwater the ring arm is so heavy you have Disadvantage on Strength and Dexterity checks. Whenever you become submerged, make a DC 20 Strength save. On a fail the arm is immobile for 1 minute, your Speed is 0, and you are dragged 30 ft down at the start of each turn. On a pass your Speed is halved and you have Disadvantage on attacks with that arm. Repeat the save each minute you stay submerged.")

add("Ring of Eldritch Ire", "Ring", "Rare", 1, "A warped ring with three swiveling gems. It has 3 charges and regains all at dusk. As a Bonus Action, spend 1 charge to mark a creature you see within 60 ft for 1 hour. You gain +1 to attack and damage rolls against it, it has -1 on saves against your spells, you know its distance and direction on the same plane, and within 60 ft you perceive it as if with Truesight, seeing through visual illusions.", by="Warlock", ch=[3, "all", "dusk"])

add("Ring of Fire", "Ring", "Rare", 0, "Cast Wall of Fire from the ring (save DC 15). It appears as a stationary 10 ft Emanation around you, 20 ft high and 1 ft thick. Once used, it works again at the next dawn.", ch=[1, "1", "dawn"])
SP["Ring of Fire"] = {"sp": [["Wall of Fire", 1]], "dc": 15}

add("Ring of Gestures", "Ring", "Common", 0, "A gaudy ring with a pink gem shaped like a hand. You can cast Minor Illusion from it to change how that hand looks, such as making fingers bigger, smaller or another color. The gem copies each gesture you make with that hand.")
SP["Ring of Gestures"] = {"sp": [["Minor Illusion", 0]]}

add("Ring of Ice", "Ring", "Very Rare", 0, "Cast Wall of Ice from the ring (save DC 16). It appears as a stationary 10 ft Emanation around you, 10 ft high and 1 ft thick. Once used, it works again at the next dawn.", ch=[1, "1", "dawn"])
SP["Ring of Ice"] = {"sp": [["Wall of Ice", 1]], "dc": 16}

add("Ring of Roses", "Ring", "Common", 0, "As a Magic action, a rose grows in your hand. It has a 1 ft stem with small dull thorns, no scent and a color you choose, and it turns to dust after 24 hours.")

add("Ring of Seething", "Ring", "Uncommon", 1, "When you attune, choose Aberration, Celestial, Dragon, Elemental, Fey, Fiend or Undead. The band glows red hot when a creature of that type is within 60 ft, though it only feels faintly warm to you. You have Advantage on saves against being Charmed or Frightened by that type.\n**Curse.** Attuning curses you until Remove Curse or similar magic. You cannot remove the ring, have Disadvantage on Wisdom (Insight) and Charisma checks involving that type, and while one is within 60 ft you have Disadvantage on attacks against creatures of other types.")

add("Ring of Stone", "Ring", "Rare", 0, "Cast Wall of Stone from the ring (save DC 16). It appears as a stationary 10 ft Emanation around you, 10 ft high and 6 inches thick. Once used, it works again at the next dawn.", ch=[1, "1", "dawn"])
SP["Ring of Stone"] = {"sp": [["Wall of Stone", 1]], "dc": 16}

add("Ring of the Fowl Sentinel", "Ring", "Common", 0, "A bronze ring stamped with a rooster. As a Magic action, tap it to the beak of a chicken or rooster that is not Hostile to make it Charmed for 8 hours. It then has AC 10, 1 HP, Speed 0, +3 to Wisdom (Perception) and stays quiet. If it sees a new Small or larger creature, or the charm ends, it crows loudly, heard out to 150 ft. Tapping it again ends the charm without a cry. Only one creature can be charmed this way at a time.")

add("Ring of the Sandskimmer", "Ring", "Uncommon", 0, "A ring of flowing sand around a spinning tiger's eye stone. You leave no footprints in sand, and sand-based Difficult Terrain costs you no extra movement.")

add("Ring of Wind", "Ring", "Uncommon", 0, "Cast Wind Wall from the ring (save DC 13). It appears as a stationary 10 ft Emanation around you, 15 ft high and 1 ft thick. Once used, it works again at the next dawn.", ch=[1, "1", "dawn"])
SP["Ring of Wind"] = {"sp": [["Wind Wall", 1]], "dc": 13}

add("Rocborne Hand Ballista", "Weapon", "Very Rare", 1, "A massive Heavy Crossbow with +1 to attack and damage rolls and twin handles. It uses twice the normal ammunition, deals an extra 1d10 Piercing on a hit, and screeches audibly out to 100 ft when fired. It has 5 charges and regains 1d4 + 1 at dawn. When you hit a Huge or smaller creature with a ranged attack, spend 1 charge. It makes a DC 16 Constitution save or has Speed 0 and cannot make Opportunity Attacks until the start of your next turn.", fx={"atk": 1, "dmg": 1}, base=["Heavy Crossbow"], ch=[5, "1d4+1", "dawn"], xd=["Always: +1d10 Piercing"])

add("Rocborne Robe", "Wondrous Item", "Uncommon", 1, "A warm canvas robe lined with roc down that lets you tolerate temperatures of 0 degrees F or lower. It has 5 charges and regains 1d4 + 1 at dawn. As a Magic action, spend 1 charge to flap wings that blast a 15 ft wide, 10 ft long Line of wind. Each Medium or smaller creature there makes a DC 13 Strength save or is pushed 10 ft away. You are flung 10 ft backward without provoking Opportunity Attacks.", ch=[5, "1d4+1", "dawn"])

add("Rocborne Rod", "Rod", "Rare", 1, "A rod carved with five rocs and holding 5 charges, regaining 1d4 + 1 at dawn. Spend 1 charge, as a Reaction while falling or a Magic action otherwise, to grow wings that slow your fall to 10 ft per round (20 ft if you weigh over 200 lb). You can move as if you had a 40 ft Fly Speed but not upward, and you take no fall damage. Spend 1 charge as a Magic action to blast a 20 ft radius, 60 ft high Cylinder near you. Large and smaller creatures make a DC 15 Strength save or are launched 30 ft up, as are loose objects under 200 lb. You can choose to fail, and if you also call the wings you launch 60 ft.", ch=[5, "1d4+1", "dawn"])

add("Sandstorm Dancer", "Wondrous Item", "Rare", 1, "A golden cloak that billows illusory sand. It has 8 charges and regains 1d6 + 2 at dawn. Spend charges to cast Blur (2), Call Lightning (3), Create or Destroy Water (1) or Hallucinatory Terrain (4), save DC 15.", ch=[8, "1d6+2", "dawn"])
SP["Sandstorm Dancer"] = {"sp": [["Blur", 2], ["Call Lightning", 3], ["Create or Destroy Water", 1], ["Hallucinatory Terrain", 4]], "dc": 15}

add("Scholar's Cap +1", "Wondrous Item", "Uncommon", 1, "A hat holding the knowledge of past scholars. You gain +1 to Intelligence checks and Intelligence saving throws. For every 5 days of research on a subject, you gain 1 extra day of knowledge.")
add("Scholar's Cap +2", "Wondrous Item", "Rare", 1, "A hat holding the knowledge of past scholars. You gain +2 to Intelligence checks and Intelligence saving throws. For every 5 days of research on a subject, you gain 2 extra days of knowledge.")
add("Scholar's Cap +3", "Wondrous Item", "Very Rare", 1, "A hat holding the knowledge of past scholars. You gain +3 to Intelligence checks and Intelligence saving throws. For every 5 days of research on a subject, you gain 3 extra days of knowledge.")

add("Scorching Cleaver", "Weapon", "Very Rare", 1, "A Battleaxe with +1 to attack and damage rolls and 8 charges, regaining 1d6 + 2 at dawn. While it has at least 1 charge, hits deal an extra 1d6 Fire. A natural 20 on an attack restores 3 charges.\n**Erupting Slash.** Magic action, spend 3 or more charges: a 5 ft wide, 30 ft long Line of fire. Creatures in it make a Dexterity save (DC 8 + Proficiency Bonus + charges spent) or take 1d6 Fire per charge spent. If you spend 4 or more and leave it at 0 charges, it overheats for an extra 3d6 Fire, and a successful save halves the damage.", fx={"atk": 1, "dmg": 1}, base=["Battleaxe"], ch=[8, "1d6+2", "dawn"], xd=["Has charges: +1d6 Fire"])

add("Screaming Longbow", "Weapon", "Rare", 1, "A sickly Longbow whose arrows howl audibly out to 100 ft. A hit deals an extra 2d4 Thunder. On a natural 20, the target and each creature within 5 ft of it make a DC 15 Constitution save or are Deafened for 1 minute.", base=["Longbow"], xd=["Always: +2d4 Thunder"])

add("Sea Serpent Hairpin", "Wondrous Item", "Uncommon", 0, "A golden hairpin coiled around a tiny silver sword. When you grapple with Unarmed Strike while submerged or swimming, the target has Disadvantage on checks and saves to avoid or end the Grappled condition.")

add("Seafarer's Jacket", "Wondrous Item", "Uncommon", 1, "A captain's jacket that sheds water. You gain a Swim Speed equal to your Speed and proficiency with Navigator's Tools (Expertise if you already had it). Once per dawn you can cast Fog Cloud from it at level 2.", fx={"swim": "walk"}, ch=[1, "1", "dawn"])
SP["Seafarer's Jacket"] = {"sp": [["Fog Cloud", 1]]}

add("Seat Belt", "Wondrous Item", "Common", 0, "A belt you wear while standing on solid ground. As you begin to sit, spend a Bonus Action to summon an Invisible, incorporeal chair of any style that holds up to 500 lb. You cannot do anything with it except sit. It vanishes if the ground is no longer solid or you stand up.")

add("Seed of Rebirth", "Wondrous Item", "Legendary", 1, "A fist-sized seed that up to 4 creatures can attune to during a Long Rest. If each plants it together in fertile soil, it grows in 7 days into a 60 ft tree with a 30 ft Emanation canopy and one large limb per attuned creature. Once planted, no one else can attune, and attunement survives distance and death. Attunement ends if a creature commits a malicious affront to nature.\nWhen an attuned creature has been dead for 1 minute, its soul goes to the tree and its body becomes rich soil like the Plant Growth enrichment. After 1d6 + 1 days a nut falls and reveals the creature in a new body, as Reincarnate, ending its attunement. A limb dies as each attunement ends. The tree cannot be destroyed by nonmagical means, and attuned creatures sense attacks on it. When the last limb dies, the tree splits and releases another seed to a new plane.")

add("Septum Ring of the Great Minotaur", "Wondrous Item", "Very Rare", 1, "A tempered gold nose ring set with rubies. Your Strength rises by 2 (maximum 22) and you have Advantage on Strength checks. Your carrying capacity doubles and you perfectly recall any path you traveled in the last 24 hours.")

add("Serpent Dart", "Weapon", "Uncommon", 0, "A Dart you can coat with emerald poison as a Bonus Action. The poison lasts 1 minute or until it hits a creature, which makes a DC 13 Constitution save or takes an extra 2d8 Poison and is Poisoned for 1 minute. Once used, it works again at the next dawn.", base=["Dart"], ch=[1, "1", "dawn"])

add("Servitude Choker", "Wondrous Item", "Uncommon", 1, "A necklace that animates a small object. As a Magic action, wrap it around a Small or smaller nonmagical object under 50 lb that is not attached or carried. It becomes a mindless servant under your control (AC 10, Speed 20 ft) until you remove the necklace or it takes damage. Command it with a Bonus Action within 60 ft. It does simple chores but cannot attack, activate magic items or carry over 10 lb. It lasts up to 8 hours, then the choker cannot be used for 1d8 hours.")

add("Set of Numat's Trick Tubes", "Wondrous Item", "Uncommon", 0, "Two linked ceramic tubes, each 3 inches wide and 1 ft tall. Close an object inside one and it teleports to the other, up to 2 lb at a time and never a creature. Both tubes must be on the same plane with their lids closed.")

add("Set of Secret Scribe Candles", "Wondrous Item", "Rare", 0, "Two linked candles that never run out and never ignite Paper or Parchment. Light one while the other is unlit and it burns blue. Held under a page, the blue flame burns off nonmagical ink. When you put it out, the other candle lights with an orange lavender flame that only magic can put out. Under a blank page, it burns the first page's ink onto it over 1 minute, then goes out.")

add("Shadow Drinker", "Weapon", "Very Rare", 1, "A Dagger with +1 to attack and damage rolls. When you hit a Small or larger enemy in melee, you can absorb its shadow. It then casts no shadow, and dark haze wraps you and the blade for up to 10 minutes. In the haze you are Invisible while entirely in Dim Light or Darkness. Hits deal an extra 1d6 Psychic, or 2d6 against the shadowless creature. The haze ends after you attack, deal damage or cast a spell, or as a Bonus Action, and the shadow returns. You can hold one shadow at a time, and the same creature's shadow cannot be taken again until dusk.\n**Curse.** Attuning curses you until Remove Curse or similar magic. While cursed, you have Vulnerability to Radiant damage.", fx={"atk": 1, "dmg": 1}, base=["Dagger"], xd=["Shadow haze: +1d6 Psychic (2d6 vs shadowless)"])

add("Shadow Ink", "Wondrous Item", "Uncommon", 0, "A bottle of ink that can only be seen and read in total darkness, where writing, drawings and tattoos glow with soft colored light. One bottle fills 50 pages. Detect Magic reveals only a faint trace of magic.")

add("Shadow Ward", "Wondrous Item", "Very Rare", 1, "A still cloak that drinks in light. You have Advantage on Dexterity (Stealth) checks. It has 3 charges and regains 1d3 at dusk. When you are hit by an attack, take a Reaction and spend 1 charge to halve the damage (round down) and teleport in black smoke to an unoccupied space you see within 30 ft.", ch=[3, "1d3", "dusk"])

add("Shadowshawl", "Wondrous Item", "Rare", 0, "A shawl of thick fabric that looks like spider webs. With the hood up, your face sits in a pocket of magical Darkness and you gain Darkvision 60 ft, or +60 ft if you already have it. You see through the pocket normally, and light-based effects such as Sunbeam cannot Blind you.", fx={"dark": 60})

add("Shadowsmoke Dragon Pipe", "Wondrous Item", "Rare", 0, "A pipe with 4 charges, regaining 1d3 + 1 at dawn, that leaves odorless smoke. As a Magic action, spend 1 charge to blow a smoke ring at yourself or an ally you see within 30 ft. The target can turn Invisible at once or wear the ring (one at a time, for 1 minute) and turn Invisible later with a Bonus Action. The Invisible condition lasts until the start of its next turn or until it attacks, deals damage or casts a spell.", ch=[4, "1d3+1", "dawn"])

add("Shaedenstaff", "Staff", "Very Rare", 1, "A staff from the horn of a huge Undead. It works as a Quarterstaff (Topple), and attuned you have Advantage on saves against mental stress effects. It has 15 charges and regains 2d6 + 3 at dusk. If you spend the last, roll 1d20, and on a 1 it crumbles in black smoke with a scream heard out to 300 ft.\n**Annihilating Strike.** On a melee hit, spend 1 charge for an extra 1d10 Necrotic.\n**Spells.** Using your save DC, spend charges for Calm Emotions 1, Darkness 2, Inflict Wounds 3 (level 3), Dispel Evil and Good 5 or Circle of Death 6.", by="Sorcerer, Warlock, or Wizard", base=["Quarterstaff"], ch=[15, "2d6+3", "dusk"], xd=["Spend 1 charge: +1d10 Necrotic"])
SP["Shaedenstaff"] = {"sp": [["Calm Emotions", 1], ["Darkness", 2], ["Inflict Wounds", 3], ["Dispel Evil and Good", 5], ["Circle of Death", 6]]}
